?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Solicitudes de cuenta empresarial | Administración</title><link rel="stylesheet" href="../assets/style.css?v=admin-navigation-20261015"><link rel="stylesheet" href="../assets/admin.css?v=admin-layout-20261015"></head><body><main class="wrap admin-page destination-admin"><a class="brand" href="index.php"><span>Explorando<b>Lugares</b></span></a><p><a href="index.php">← Volver al panel</a></p><h1>Solicitudes de cuenta empresarial</h1><p>Esta sección recibe solicitudes para abrir una cuenta de negocio. Puede pedir asociar un negocio existente o proponer uno que todavía no esté en el directorio. Aún no crea una ficha pública, no confirma quién lo representa ni concede acceso para editarlo.</p><?php require __DIR__.'/_navigation.php'; ?><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if($dbError):?><p class="notice" role="alert"><?=esc($dbError)?> <a href="base-datos.php">Ver estado de la base de datos</a>.</p><?php endif ?><?php if(($_GET['actualizada']??'')==='1'):?><p class="notice" role="status">Se actualizó el estado de la solicitud.</p><?php endif ?><section class="destination-admin-list"><h2>Solicitudes recibidas <small>(<?=count($applications)?>)</small></h2><?php if(!$applications&&!$dbError):?><p>Aún no hay solicitudes empresariales.</p><?php elseif($applications):?><div class="destination-admin-table"><table><thead><tr><th>Negocio solicitado</th><th>Cuenta</th><th>Solicitud</th><th>Estado</th><th>Revisión</th></tr></thead><tbody><?php foreach($applications as $item):?><tr><td><strong><?=esc($item['business_name'])?></strong><br><?=esc($item['destination_name'])?> · <?=esc($item['category_label'])?><br><small><?=esc($item['business_id']?'Registro existente #'.$item['business_id']:'Negocio nuevo por validar')?></small></td><td><?=esc($item['account_name'])?><br><?=esc($item['email'])?><br><?=esc($item['contact_phone']?:'Sin teléfono adicional')?></td><td><?=esc($item['application_type']==='claim_existing'?'Solicita asociar un registro existente':'Solicita revisar e incorporar un negocio')?><br><?=esc($item['relationship_code']==='owner'?'Propietario/a':'Representante autorizado/a')?><br><?=esc($item['message']?:'—')?></td><td><?=esc(['pending'=>'Pendiente','in_review'=>'En revisión','not_approved'=>'No aprobada'][$item['status']]??$item['status'])?><br><small><?=esc($item['created_at'])?></small></td><td><?php if(in_array($item['status'],['pending','in_review'],true)):?><form method="post" class="claim-review-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="review"><input type="hidden" name="application_id" value="<?=esc($item['id'])?>"><label>Nota interna<input name="admin_note" maxlength="1000"></label><button class="pill light" name="status" value="in_review">Marcar en revisión</button><button class="pill danger" name="status" value="not_approved" onclick="return confirm('¿Cerrar esta solicitud como no aprobada?')">No aprobada</button></form><?php else:?>Cerrada<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section></main></body></html>
